function pause() {
  car.model.visible = true; // may be hidden by the first-person camera
  g.pausedAt = performance.now();
  g.prevState = g.state;
  g.state = 'paused';
  chat.close();
  input.unlock();
  Object.assign(show, { yaw: 0.6, pitch: 0.14, dist: 9.5 });
  hud.show(false);
  car.showFX(false);
  $('pause').classList.remove('hidden');
}
